import sys, json, datetime, hashlib

# THE FOLLOW-UP (D58, GH #1479, R-58-9 Nr. 3). When the person says how they
# are doing -- a fact the model classed `wellbeing: true` in the section
# `memory` (memory-hive schema, GH #1456) -- the next conversation asks after
# it once. Until D58 the curator kept that rule (`wellbeing_line` in its
# `./policy` and `./history`); the curator keeps the window of every model and
# knows no domain, so the rule lives here, in the companion domain. The cell
# hears the section where it already crosses the hive (each child hands it out
# on `sidecar`), keeps the newest concern per round and day in its OWN store
# `./followup_store`, and hands it to the curators of the hive as a note of
# scope `once` with a `receipt` and `until` = the end of the person's day.
# The first receipt closes it, and the copies in the other curators are
# withdrawn (same id, text ""). It reads no ledger and no foreign database:
# everything it knows arrived as a message.
#
# The session that heard it never gets the note (contract point 4, review C1
# of the strand): `./policy` shows an open `once` note in the next turn of any
# session of the round, so a note sent into the hearing surface was asked in
# the very session that had just heard it, its receipt closed the concern, and
# the next conversation knew nothing. The concern is therefore HELD (`state`
# "held", the hearing `session` and `node`) for the hearing surface only,
# until that session ends: its curator hands out one `write` at every close
# (`hop.session_id`), with no knob -- `closed` (GH #1305) only comes with
# `conversation_events` "1". The other children get it at once (re-check
# I1): a chat session on `./talky-chat` ends only after the keeper's idle
# threshold (2 h as shipped), and a call in between must know it in its start
# window. The hold is per surface, not per session (OR-d58-2.followup.29): a
# channel that shares the hearing surface (today Telegram and a call, both on
# `./talky`) sees it only after the hearing session has ended. The
# hearing surface is the one the section came from, told by the key the hive
# already splits its surfaces by, `context.channel_node` (`chat` =
# `./talky-chat`, anything else `./talky`); it rides out on `hop.channel_node`
# because a cell writes no context. The hive's edges hold the reasoning core
# `./cogny` like the hearing surface (OR-d58-2.followup.27): the hearing
# session consults it, and a receipt from it would close the concern before
# the next conversation. The first receipt, from any child, closes the
# concern and withdraws every copy -- a held one is then never sent.
# A concern heard without a session (`context.session_id` absent) has no
# running window to keep it from and goes to every child at once.
#
# Every write also sweeps the rows of past days (review M3): they name what
# the person said about their health and serve nothing after their day.
#
# Lanes in: `sidecar` (hop.section `memory`), `write` (a session ended),
# `note_receipt`, and the answers of its store (context.cur_origin
# `followup`). Out: `fstore` (its store), `in_note` (the hive's edges carry
# it to every child with a curator; with `hop.channel_node` set only to the
# surface that did not hear it) and `in_note_held` (to the hearing surface
# `hop.channel_node` names and to `./cogny`). At most two messages per run: a
# replaced concern's withdrawal goes to every child, its successor not.
doc = json.load(sys.stdin)
d = doc.get("body") or {}
envelope = doc.get("envelope") or {}
P = doc.get("params") or {}
header = envelope.get("header") or {}
hop = header.get("hop") or {}
ctx = header.get("context") or {}
ME = "followup"
SOURCE = "assistant"
ID_PREFIX = "fu-"
TABLE = "followup"


def unset(v):
    return v is None or (isinstance(v, str) and not v.strip())


def switch_on(v):
    """One switch (#1370): JSON true, "1", "true" or "on" is on."""
    return str(v).strip().lower() in ("1", "true", "on")


def knob_float(name, default):
    v = P.get(name)
    if unset(v) or isinstance(v, bool):
        return default
    try:
        return float(str(v))
    except ValueError:
        return default


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def loads(text, default):
    try:
        return json.loads(text)
    except (TypeError, ValueError):
        return default


ENABLED = switch_on(P.get("enabled", "0"))
MIN_CONFIDENCE = knob_float("min_confidence", 0.6)
NOTE_TEXT = str(P.get("note_text") or "") or "{claim}"
TIMEZONE = str(P.get("timezone") or "").strip()
NOW_FIXED = str(P.get("now_utc") or "").strip()


def now_local():
    """The instant in the instance's zone (`timezone`; "" or an unknown zone:
    UTC, the latter said on stderr); `now_utc` fixes the instant for a test."""
    zone = datetime.timezone.utc
    if TIMEZONE:
        try:
            import zoneinfo
            zone = zoneinfo.ZoneInfo(TIMEZONE)
        except Exception:
            sys.stderr.write("assistant/followup: unknown timezone %r -- UTC\n" % TIMEZONE)
    t = None
    if NOW_FIXED:
        try:
            t = datetime.datetime.fromisoformat(NOW_FIXED.replace("Z", "+00:00"))
            if t.tzinfo is None:
                t = t.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            sys.stderr.write("assistant/followup: now_utc %r is no RFC 3339 time\n" % NOW_FIXED)
            t = None
    if t is None:
        # wall-clock: now_utc
        t = datetime.datetime.now(datetime.timezone.utc)
    return t.astimezone(zone)


def day_and_end(local):
    """The person's day (`YYYY-MM-DD` in the zone) and its end in UTC (the next
    local midnight, RFC 3339): the note never outlives the day it was said on."""
    nxt = local.date() + datetime.timedelta(days=1)
    end = datetime.datetime(nxt.year, nxt.month, nxt.day, tzinfo=local.tzinfo)
    end = end.astimezone(datetime.timezone.utc)
    return local.date().isoformat(), end.strftime("%Y-%m-%dT%H:%M:%SZ")


def round_tag(value):
    """A short stable tag of the round (`context.audience_set`, a JSON array as
    text or a list): one person, one concern per day."""
    v = value
    if isinstance(v, str):
        v = loads(v, v)
    if isinstance(v, list):
        v = sorted(str(x) for x in v)
    return hashlib.sha256(canonical(v).encode("utf-8")).hexdigest()[:10]


def row_key(day, tag):
    return "open:%s:%s" % (day, tag)


def note_id(day, tag, n):
    return "%s%s-%s-%d" % (ID_PREFIX, day, tag, n)


def key_of_id(nid):
    """`fu-<day>-<tag>-<n>` -> the row key, or "" for an id that is not ours."""
    if not nid.startswith(ID_PREFIX):
        return ""
    parts = nid[len(ID_PREFIX):].rsplit("-", 2)
    if len(parts) != 3 or not parts[2].isdigit() or len(parts[0]) != 10:
        return ""
    return row_key(parts[0], parts[1])


def concern_of(facts):
    """The newest fact of the list classed `wellbeing: true` whose confidence
    is at least `min_confidence` (a fact without one passes, OR-d38-3.v.9),
    as {claim, subject, predicate}; None when there is none."""
    found = None
    for f in facts if isinstance(facts, list) else []:
        if not isinstance(f, dict) or f.get("wellbeing") is not True:
            continue
        claim = f.get("claim")
        if not isinstance(claim, str) or not claim.strip():
            continue
        conf = f.get("confidence")
        if conf is not None:
            if isinstance(conf, bool) or not isinstance(conf, (int, float)):
                continue
            if conf < MIN_CONFIDENCE:
                continue
        found = {"claim": claim.strip(), "subject": str(f.get("subject") or ""),
                 "predicate": str(f.get("predicate") or "")}
    return found


def text_of(c):
    t = NOTE_TEXT
    for k in ("claim", "subject", "predicate"):
        t = t.replace("{" + k + "}", c[k])
    return t


def fstore(ops, phase, carry):
    return {"header": {"route": "fstore", "phase": phase, "reply_cell": ME,
                       "cur_carry": canonical(carry)},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                          "text": json.dumps(args)} for cid, args in ops]}


def notes(items):
    """To every child with a curator."""
    return {"header": {"route": "in_note"}, "messages": [], "notes": items}


def notes_except(node, items):
    """To the surface `node` does not name (the edges hold `./cogny`)."""
    return {"header": {"route": "in_note", "channel_node": node}, "messages": [],
            "notes": items}


def notes_held(node, items):
    """To the hearing surface `node` names, and to `./cogny`."""
    return {"header": {"route": "in_note_held", "channel_node": node}, "messages": [],
            "notes": items}


def withdrawal(nid):
    return {"id": nid, "source": SOURCE, "text": "", "scope": "once"}


def legs(body):
    """The legs of a store answer: payload, error_code, rows_affected per id."""
    out = {}
    for m in body.get("messages") or []:
        if isinstance(m, dict):
            out[str(m.get("id") or "")] = {"payload": loads(str(m.get("text") or "null"), None),
                                           "error_code": "", "rows_affected": 0}
    results = body.get("results")
    if isinstance(results, list):
        for r in results:
            if isinstance(r, dict):
                leg = out.setdefault(str(r.get("tool_call_id") or ""),
                                     {"payload": None, "error_code": "", "rows_affected": 0})
                leg["error_code"] = str(r.get("error_code") or "")
                leg["rows_affected"] = int(r.get("rows_affected") or 0)
    elif len(out) == 1:
        leg = next(iter(out.values()))
        leg["error_code"] = str(hop.get("error_code") or "")
        leg["rows_affected"] = int(hop.get("rows_affected") or 0)
    return out


def row_of(lg, cid):
    """The one row of a select leg as (raw value, parsed value) or ("", None)."""
    p = (lg.get(cid) or {}).get("payload")
    for r in p if isinstance(p, list) else []:
        if isinstance(r, dict) and isinstance(r.get("value"), str):
            return r["value"], loads(r["value"], None)
    return "", None


def emit(msgs):
    sys.stdout.write(json.dumps(list(msgs)))
    sys.exit(0)


def write(op, phase, carry):
    """One write of the own store, bundled with the sweep of the rows of past
    days (keys sort by day: `open:<day>:<tag>`). No timer, no polling: the
    store is cleaned when it is written anyway."""
    today = day_and_end(now_local())[0]
    sweep = {"operation": "delete", "table": TABLE,
             "where": {"key": {"lt": "open:" + today}}}
    return fstore([("write", op), ("sweep", sweep)], phase, carry)


def note_item(new):
    return {"id": new.get("id", ""), "source": SOURCE, "text": new.get("text", ""),
            "scope": "once", "receipt": new.get("receipt", ""), "until": new.get("until", "")}


def session_of():
    return str(ctx.get("session_id") or hop.get("session_id") or "").strip()


def node_of():
    """The channel node the section came in by: the key `assistant` routes
    its surfaces by (`chat` -> `./talky-chat`, anything else -> `./talky`)."""
    return str(ctx.get("channel_node") or "").strip()


def read(key, phase, carry):
    return fstore([("read", {"operation": "select", "table": TABLE,
                             "columns": ["key", "value"], "where": {"key": key}})],
                  phase, carry)


if True:
    lane = str(hop.get("route") or "")
    if str(ctx.get("cur_origin") or "") == ME:
        # An answer of the own store: the phase it was asked in decides.
        phase = str(ctx.get("cur_phase") or "")
        carry = loads(str(ctx.get("cur_carry") or "{}"), {})
        carry = carry if isinstance(carry, dict) else {}
        lg = legs(d)
        if phase == "f-read":
            # A concern heard: open it, replace the open one, or nothing.
            raw, old = row_of(lg, "read")
            c = carry.get("concern") or {}
            key = str(carry.get("key") or "")
            session = str(carry.get("session") or "")
            if old is not None and old.get("claim") == c.get("claim") and not (
                    old.get("state") == "held" and session
                    and old.get("session") != session):
                # Said again: still open (the note stands), asked after
                # already (closed), or held for this very session -- nothing.
                # Held for ANOTHER session, it is replaced like a new concern
                # (review M6): that session's end may never come (a close the
                # store refused twice), and the hold would mute the day.
                emit([])
            n = int(old.get("n") or 0) + 1 if isinstance(old, dict) else 1
            nid = note_id(carry.get("day", ""), carry.get("tag", ""), n)
            receipt = hashlib.sha256((nid + "\n" + c.get("claim", "")).encode("utf-8")).hexdigest()[:16]
            # Held for the hearing surface while its session runs (the other
            # children get it at once); without a session, open everywhere.
            new = {"id": nid, "n": n, "claim": c.get("claim", ""), "receipt": receipt,
                   "state": "held" if session else "open", "session": session,
                   "node": str(carry.get("node") or ""),
                   "text": text_of(c), "until": carry.get("until", "")}
            # A note that went out is withdrawn everywhere: an open one, and a
            # held one too (it is out at every child but the hearing surface).
            gone = old.get("id") if isinstance(old, dict) \
                and old.get("state") in ("open", "held") else ""
            if old is None:
                op = {"operation": "insert", "table": TABLE,
                      "row": {"key": key, "value": canonical(new)}, "if_absent": {"key": key}}
            else:
                # Compare-and-set on the value read: a concurrent write wins,
                # this one sends nothing.
                op = {"operation": "update", "table": TABLE, "set": {"value": canonical(new)},
                      "where": {"key": key, "value": raw}}
            emit([write(op, "f-write", {"note": new, "gone": gone or ""})])
        if phase == "f-write":
            if (lg.get("write") or {}).get("rows_affected", 0) < 1:
                sys.stderr.write("assistant/followup: the concern moved meanwhile -- nothing sent\n")
                emit([])
            new = carry.get("note") or {}
            items = [withdrawal(carry["gone"])] if carry.get("gone") else []
            if new.get("state") == "open":
                emit([notes(items + [note_item(new)])])
            # Held: the withdrawal reaches every child, the note all but the
            # hearing surface.
            emit(([notes(items)] if items else [])
                 + [notes_except(str(new.get("node") or ""), [note_item(new)])])
        if phase == "w-read":
            # A session ended: the concern it heard and holds goes out now,
            # to the hearing surface only -- the others have it already.
            raw, old = row_of(lg, "read")
            if not isinstance(old, dict) or old.get("state") != "held" \
                    or old.get("session") != carry.get("session"):
                emit([])
            opened = dict(old, state="open")
            emit([write({"operation": "update", "table": TABLE,
                         "set": {"value": canonical(opened)},
                         "where": {"key": carry.get("key", ""), "value": raw}},
                        "w-write", {"note": opened})])
        if phase == "w-write":
            if (lg.get("write") or {}).get("rows_affected", 0) < 1:
                sys.stderr.write("assistant/followup: the concern moved meanwhile -- nothing sent\n")
                emit([])
            note = carry.get("note") or {}
            emit([notes_held(str(note.get("node") or ""), [note_item(note)])])
        if phase == "r-read":
            # A receipt: the first one that names the note closes it, open or
            # still held for the hearing surface (a child that did not hear
            # it asked after it; the held copy is then never sent).
            raw, old = row_of(lg, "read")
            if not isinstance(old, dict) or old.get("state") not in ("open", "held") \
                    or old.get("id") != carry.get("id") \
                    or old.get("receipt") != carry.get("receipt"):
                emit([])
            closed = dict(old, state="closed")
            emit([write({"operation": "update", "table": TABLE,
                         "set": {"value": canonical(closed)},
                         "where": {"key": carry.get("key", ""), "value": raw}},
                        "r-write", {"id": old.get("id", "")})])
        if phase == "r-write":
            if (lg.get("write") or {}).get("rows_affected", 0) < 1:
                emit([])
            # Asked after: the copies in the other curators go (every child;
            # one that never had it writes an ended row, nothing shows).
            emit([notes([withdrawal(str(carry.get("id") or ""))])])
        emit([])
    if not ENABLED:
        # Off (shipped): nothing read, nothing written, nothing sent.
        emit([])
    if lane == "sidecar" and str(hop.get("section") or "") == "memory":
        payload = d.get("payload") if isinstance(d.get("payload"), dict) else {}
        c = concern_of(payload.get("facts"))
        if c is None:
            emit([])
        day, until = day_and_end(now_local())
        tag = round_tag(ctx.get("audience_set"))
        key = row_key(day, tag)
        emit([read(key, "f-read", {"concern": c, "key": key, "day": day, "tag": tag,
                                   "until": until, "session": session_of(),
                                   "node": node_of()})])
    if lane == "write":
        # A session of a child ended (its curator's close, one per close).
        session = session_of()
        if not session:
            emit([])
        key = row_key(day_and_end(now_local())[0], round_tag(ctx.get("audience_set")))
        emit([read(key, "w-read", {"key": key, "session": session})])
    if lane == "note_receipt":
        if str(hop.get("note_source") or "") != SOURCE:
            emit([])
        nid = str(hop.get("note_id") or "")
        key = key_of_id(nid)
        if not key:
            emit([])
        emit([read(key, "r-read", {"id": nid, "receipt": str(hop.get("receipt") or ""),
                                   "key": key})])
    emit([])
